using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class WillowTemporary{
const string F="Assets/LevelDesign/Prefabs/Природа/Растительность/Деревья/Лиственные/Облиственные/";const string T="Assets/LevelDesign/Textures/Shared/Willow_Leaves_01.png";
static WillowTemporary(){EditorApplication.delayCall+=Build;}
class Geo{public List<Vector3> v=new List<Vector3>();public List<Vector2> uv=new List<Vector2>();public List<int> t=new List<int>();public void Card(Vector3 p,Vector3 r,Vector3 u,float w,float h){int n=v.Count;v.AddRange(new[]{p-r*w/2-u*h/2,p+r*w/2-u*h/2,p+r*w/2+u*h/2,p-r*w/2+u*h/2});uv.AddRange(new[]{Vector2.zero,Vector2.right,Vector2.one,Vector2.up});t.AddRange(new[]{n,n+1,n+2,n,n+2,n+3});}public Mesh Mesh(string name){var m=new Mesh{name=name};m.SetVertices(v);m.SetUVs(0,uv);m.SetTriangles(t,0);m.RecalculateNormals();m.RecalculateBounds();return m;}}
static MeshRenderer Part(GameObject root,string name,Mesh mesh,Material mat){var g=new GameObject(name);g.transform.SetParent(root.transform,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;var r=g.AddComponent<MeshRenderer>();r.sharedMaterial=mat;return r;}
static void Build(){if(File.Exists("Temp/willow-result.txt"))return;try{if(File.Exists(F+"Willow.prefab"))throw new Exception("Target exists");AssetDatabase.ImportAsset(T);var ti=(TextureImporter)AssetImporter.GetAtPath(T);ti.alphaIsTransparency=true;ti.mipmapEnabled=true;ti.mipMapsPreserveCoverage=true;ti.alphaTestReferenceValue=.5f;ti.wrapMode=TextureWrapMode.Clamp;ti.SaveAndReimport();
var source=AssetDatabase.FindAssets("Tree Type6 04 t:Prefab").Select(AssetDatabase.GUIDToAssetPath).First(p=>Path.GetFileName(p)=="Tree Type6 04.prefab");var m=AssetDatabase.LoadAssetAtPath<GameObject>(source).GetComponent<MeshFilter>().sharedMesh;var vs=m.vertices;var uv=m.uv;var ids=m.triangles;float scale=6f/m.bounds.size.y;var b=m.bounds;Vector3 Convert(Vector3 p)=>new Vector3(p.x-b.center.x,p.y-b.min.y,p.z-b.center.z)*scale;
var bark=new Geo();var surfaces=new List<(Vector3 a,Vector3 b,Vector3 c,float area)>();float total=0;for(int i=0;i<ids.Length;i+=3){var a=Convert(vs[ids[i]]);var bb=Convert(vs[ids[i+1]]);var c=Convert(vs[ids[i+2]]);if(uv[ids[i]].y>.6f){int n=bark.v.Count;bark.v.AddRange(new[]{a,bb,c});bark.uv.AddRange(new[]{Vector2.zero,Vector2.zero,Vector2.zero});bark.t.AddRange(new[]{n,n+1,n+2});}else{total+=Vector3.Cross(bb-a,c-a).magnitude*.5f;surfaces.Add((a,bb,c,total));}}if(bark.t.Count==0||surfaces.Count==0)throw new Exception("Classification failed");
var trunk=bark.Mesh("Willow_Branches");AssetDatabase.CreateAsset(trunk,F+"Willow.asset");var bm=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="Willow_Bark"};bm.SetColor("_BaseColor",new Color(.25f,.20f,.13f));bm.SetFloat("_Smoothness",.04f);AssetDatabase.CreateAsset(bm,F+"Willow_Bark.mat");var lm=new Material(bm){name="Willow_Leaves"};lm.SetColor("_BaseColor",Color.white);lm.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(T));lm.SetFloat("_AlphaClip",1);lm.SetFloat("_Cutoff",.5f);lm.SetFloat("_Cull",0);lm.SetFloat("_AlphaToMask",0);lm.EnableKeyword("_ALPHATEST_ON");lm.SetOverrideTag("RenderType","TransparentCutout");lm.renderQueue=2450;lm.doubleSidedGI=true;AssetDatabase.CreateAsset(lm,F+"Willow_Leaves.mat");
var meshes=new Mesh[3];for(int lod=0;lod<3;lod++){var random=new System.Random(678);var g=new Geo();int count=new[]{650,360,180}[lod];float size=new[]{1f,1.22f,1.5f}[lod];for(int i=0;i<count;i++){float pick=(float)random.NextDouble()*total;var s=surfaces.First(x=>x.area>=pick);float u=Mathf.Sqrt((float)random.NextDouble()),w=(float)random.NextDouble();var p=s.a*(1-u)+s.b*u*(1-w)+s.c*u*w;float angle=(float)random.NextDouble()*360;for(int j=0;j<2;j++){var q=Quaternion.Euler(0,angle+j*90,0);g.Card(p-Vector3.up*.12f,q*Vector3.right,Vector3.up,.72f*size,1.05f*size);}}meshes[lod]=g.Mesh("Willow_Leaves_LOD"+lod);AssetDatabase.AddObjectToAsset(meshes[lod],trunk);}AssetDatabase.SaveAssetIfDirty(trunk);
var root=new GameObject("Willow");var br=Part(root,"Ствол и ветви",trunk,bm);var lods=new LOD[3];for(int lod=0;lod<3;lod++)lods[lod]=new LOD(new[]{.18f,.07f,.01f}[lod],new Renderer[]{br,Part(root,"Листья LOD"+lod,meshes[lod],lm)});var group=root.AddComponent<LODGroup>();group.SetLODs(lods);group.RecalculateBounds();var col=root.AddComponent<CapsuleCollider>();col.radius=.52f;col.height=3;col.center=new Vector3(0,1.5f,0);var prefab=PrefabUtility.SaveAsPrefabAsset(root,F+"Willow.prefab");UnityEngine.Object.DestroyImmediate(root);Preview(prefab,0);Preview(prefab,2);File.WriteAllText("Temp/willow-result.txt","Branches: "+trunk.triangles.Length/3+"\nLeaves: "+string.Join(" / ",meshes.Select(x=>x.triangles.Length/3))+"\nThree LODs, capsule, height approximately 6m");}catch(Exception e){File.WriteAllText("Temp/willow-error.txt",e.ToString());}}
static void Preview(GameObject prefab,int lod){var util=new PreviewRenderUtility();var clone=UnityEngine.Object.Instantiate(prefab);util.AddSingleGO(clone);clone.GetComponent<LODGroup>().ForceLOD(lod);var b=clone.GetComponentsInChildren<Renderer>().First().bounds;foreach(var r in clone.GetComponentsInChildren<Renderer>())b.Encapsulate(r.bounds);var cam=util.camera;cam.orthographic=true;cam.orthographicSize=Mathf.Max(b.extents.x,b.extents.y)*1.25f;cam.transform.position=b.center+new Vector3(9,3,-16);cam.transform.LookAt(b.center);cam.nearClipPlane=.01f;cam.farClipPlane=60;cam.clearFlags=CameraClearFlags.Color;cam.backgroundColor=new Color(.46f,.5f,.53f);util.lights[0].intensity=1.3f;util.lights[0].transform.rotation=Quaternion.Euler(40,-35,0);util.lights[1].intensity=.6f;util.ambientColor=Color.gray;util.BeginStaticPreview(new Rect(0,0,1000,900));util.Render(true);var tex=util.EndStaticPreview();File.WriteAllBytes("Temp/Willow-"+lod+".png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);util.Cleanup();}
}
